using System;
using System.Linq;

[Serializable]
public class NumVarStat : VarStat<float>
{
	public bool syncCurrentToModMax;

	public float minMaxVal;

	public override float CurrentValue
	{
		get
		{
			return (!syncCurrentToModMax) ? _currentValue : ModifiedValue;
		}
		set
		{
			_currentValue = ((!syncCurrentToModMax && !(value > ModifiedValue)) ? value : ModifiedValue);
			if (_currentValue < 0f)
			{
				_currentValue = 0f;
			}
			AnnounceStatChangedEvent();
		}
	}

	public override float BaseValue
	{
		get
		{
			return _baseValue;
		}
		set
		{
			_baseValue = ((!(value > minMaxVal)) ? minMaxVal : value);
		}
	}

	public override float ModifiedValue
	{
		get
		{
			return _modifiedValue;
		}
		set
		{
			_modifiedValue = ((!(value > minMaxVal)) ? minMaxVal : value);
		}
	}

	public NumVarStat(float newBaseVal, bool syncCurrentToModMax = false)
		: base(newBaseVal)
	{
		CurrentValue = newBaseVal;
		this.syncCurrentToModMax = syncCurrentToModMax;
	}

	public NumVarStat(int newBaseVal)
		: this(newBaseVal, false)
	{
	}

	public override void Reprioritize()
	{
		modifiers = (from x in modifiers
			orderby x.modType, ((NumVarStatMod)x).priority, ((NumVarStatMod)x).modValue descending
			select x).ToList();
	}
}
using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;

[Serializable]
public class VarStat<T> : ISerializationCallbackReceiver
{
	public delegate void StatChangedEventHandler();

	private VarStatMod<T> topPriorityOverride;

	public StatChangedEventHandler statChangedEventHandlers;

	public T _currentValue;

	public T _baseValue;

	public T _modifiedValue;

	public int overrideModCount;

	public List<VarStatMod<T>> modifiers;

	public virtual T CurrentValue
	{
		get
		{
			return _currentValue;
		}
		set
		{
			_currentValue = value;
			AnnounceStatChangedEvent();
		}
	}

	public virtual T BaseValue
	{
		get
		{
			return _baseValue;
		}
		set
		{
			_baseValue = value;
			Recalculate();
		}
	}

	public virtual T ModifiedValue
	{
		get
		{
			return _modifiedValue;
		}
		set
		{
			_modifiedValue = value;
		}
	}

	public bool HasOverrideMod => overrideModCount > 0;

	public VarStat(T newBaseVal)
	{
		Initialize(newBaseVal);
	}

	public void Initialize(T newBaseVal, bool initModList = true)
	{
		BaseValue = newBaseVal;
		ModifiedValue = newBaseVal;
		CurrentValue = newBaseVal;
		if (initModList)
		{
			modifiers = new List<VarStatMod<T>>();
		}
	}

	public void OnBeforeSerialize()
	{
	}

	public virtual void OnAfterDeserialize()
	{
		Initialize(_baseValue);
	}

	public virtual int GetModIndex(string modID)
	{
		for (int i = 0; i < modifiers.Count; i++)
		{
			if (modifiers[i].ID == modID)
			{
				return i;
			}
		}
		return -1;
	}

	public virtual void Reset()
	{
		modifiers.Clear();
		overrideModCount = 0;
		topPriorityOverride = null;
		Recalculate();
	}

	public virtual void Modify(VarStatMod<T> givenMod, bool addMod)
	{
		if (addMod)
		{
			AddMod(givenMod);
		}
		else
		{
			RemoveMod(givenMod);
		}
	}

	public virtual void AddMod(VarStatMod<T> newMod)
	{
		int modIndex = GetModIndex(newMod.ID);
		if (modIndex != -1)
		{
			modifiers[modIndex] = newMod;
		}
		else
		{
			modifiers.Add(newMod);
		}
		Reprioritize();
		SetTopPriorityOverride();
		Recalculate();
		if (newMod.modType == VarStatModType.Override)
		{
			overrideModCount++;
		}
	}

	public virtual void RemoveMod(VarStatMod<T> givenMod)
	{
		if (givenMod != null)
		{
			RemoveMod(givenMod.ID);
			if (givenMod.modType == VarStatModType.Override)
			{
				overrideModCount--;
			}
		}
	}

	public virtual void RemoveMod(string modID)
	{
		int modIndex = GetModIndex(modID);
		if (modIndex != -1)
		{
			modifiers[modIndex].Remove(this);
			modifiers.Remove(modifiers[modIndex]);
			Reprioritize();
			SetTopPriorityOverride();
			Recalculate();
		}
	}

	public void SetTopPriorityOverride()
	{
		for (int i = 0; i < modifiers.Count; i++)
		{
			if (modifiers[i].modType == VarStatModType.Override)
			{
				topPriorityOverride = modifiers[i];
				return;
			}
		}
		topPriorityOverride = null;
	}

	public virtual void Recalculate()
	{
		if (modifiers == null)
		{
			return;
		}
		ModifiedValue = BaseValue;
		if (topPriorityOverride != null)
		{
			topPriorityOverride.Apply(this);
		}
		else
		{
			for (int i = 0; i < modifiers.Count; i++)
			{
				modifiers[i].Apply(this);
			}
		}
		CurrentValue = CurrentValue;
	}

	public virtual void Reprioritize()
	{
		modifiers = (from x in modifiers
			orderby x.modType, x.priority
			select x).ToList();
	}

	public void SetInitialBaseValue(T newBaseVal)
	{
		Initialize(newBaseVal, initModList: false);
	}

	public void AnnounceStatChangedEvent()
	{
		if (statChangedEventHandlers != null)
		{
			statChangedEventHandlers();
		}
	}
}
public class VarStatMod<T>
{
	public string ID;

	public int priority;

	public int defaultPriority = 10;

	public VarStatModType modType;

	public VarStatMod(string newID, int newPriority = 0, VarStatModType modType = VarStatModType.Additive)
	{
		ID = newID;
		priority = newPriority;
		this.modType = modType;
	}

	public virtual void Apply(VarStat<T> varStatToMod)
	{
	}

	public virtual void Remove(VarStat<T> varStatToMod)
	{
	}
}
public enum VarStatModType
{
	Override = 0,
	OverrideWithMods = 1,
	Multiplicative = 2,
	Additive = 3,
	LateMultiplicative = 4,
	Custom = 8
}
public class NumVarStatMod : VarStatMod<float>
{
	public float modValue;

	public bool fillToNewMax;

	public NumVarStatMod(string newID, float newModValue, int newPriority = 10, VarStatModType modType = VarStatModType.Additive, bool fillToNewMax = false)
		: base(newID, newPriority, modType)
	{
		modValue = newModValue;
		base.modType = modType;
		this.fillToNewMax = fillToNewMax;
	}

	public void ApplyMultiplicative(VarStat<float> varStatToMod)
	{
		varStatToMod.ModifiedValue += varStatToMod.ModifiedValue * (1f + modValue) - varStatToMod.ModifiedValue;
	}

	public override void Apply(VarStat<float> varStatToMod)
	{
		base.Apply(varStatToMod);
		if (modType == VarStatModType.Override || modType == VarStatModType.OverrideWithMods)
		{
			varStatToMod.ModifiedValue = modValue;
		}
		else
		{
			switch (modType)
			{
			case VarStatModType.Additive:
				varStatToMod.ModifiedValue += modValue;
				break;
			case VarStatModType.Multiplicative:
				ApplyMultiplicative(varStatToMod);
				break;
			case VarStatModType.LateMultiplicative:
				ApplyMultiplicative(varStatToMod);
				break;
			}
		}
		if (fillToNewMax)
		{
			varStatToMod.CurrentValue = varStatToMod.ModifiedValue;
		}
	}

	public new void Remove(VarStat<float> varStatToMod)
	{
		base.Apply(varStatToMod);
	}
}
public static class EmpowerStatMods
{
	private static BoolVarStatMod _defaultEmpowerMod;

	private static BoolVarStatMod _debugEmpowerMod;

	public static BoolVarStatMod DefaultEmpowerMod
	{
		get
		{
			if (_defaultEmpowerMod == null)
			{
				_defaultEmpowerMod = new BoolVarStatMod("DefaultEmpower", newModValue: true, 60);
			}
			return _defaultEmpowerMod;
		}
	}

	public static BoolVarStatMod DebugEmpowerMod
	{
		get
		{
			if (_debugEmpowerMod == null)
			{
				_debugEmpowerMod = new BoolVarStatMod("DebugEmpower", newModValue: true, 0);
			}
			return _debugEmpowerMod;
		}
	}
}
public enum EmpowerModPriority
{
	Default = 60,
	Item1 = 50,
	Item0 = 40,
	ItemNegative = 20,
	Override = 10,
	Debug = 0
}
using System;

[Serializable]
public class SyncedNumVarStat : NumVarStat
{
	public SyncedNumVarStat(float newBaseVal)
		: base(newBaseVal, syncCurrentToModMax: true)
	{
	}

	public override void OnAfterDeserialize()
	{
		base.OnAfterDeserialize();
		syncCurrentToModMax = true;
	}
}
using System;
using System.Linq;

[Serializable]
public class BoolVarStat : VarStat<bool>
{
	public BoolVarStat(bool newBaseVal)
		: base(newBaseVal)
	{
	}

	public override void Reprioritize()
	{
		modifiers = (from x in modifiers
			orderby x.modType descending, x.priority
			select x).ToList();
	}

	public override void Recalculate()
	{
		CurrentValue = BaseValue;
		base.Recalculate();
	}
}
public class BoolVarStatMod : VarStatMod<bool>
{
	public bool modValue;

	public BoolVarStatMod(string newID, bool newModValue, int newPriority = 10)
		: base(newID, newPriority, VarStatModType.Additive)
	{
		modValue = newModValue;
	}

	public BoolVarStatMod(string newID, BoolVarStatMod newMod)
		: base(newID, newMod.priority, VarStatModType.Additive)
	{
		modValue = newMod.modValue;
	}

	public override void Apply(VarStat<bool> varStatToMod)
	{
		base.Apply(varStatToMod);
		varStatToMod.CurrentValue = modValue;
		varStatToMod.ModifiedValue = modValue;
	}
}

using System.Collections.Generic;
using System.Linq;
using UnityEngine;

public static class StatManager
{
	public delegate bool ModApplyConditional(StatData givenStatData);

	private static readonly string statFieldStr = "Skills";

	private static readonly string playerSkillAssetPath = "Assets/Data/Player/Skills.json";

	private static readonly string playerBaseCategory = "Player";

	private static readonly string enemySkillAssetPath = "Assets/Data/Enemy/Skills.json";

	public static readonly string enemyBaseCategory = "Enemy";

	public static Dictionary<string, StatData> globalSkillData = new Dictionary<string, StatData>();

	public static Dictionary<string, Dictionary<string, Dictionary<string, StatData>>> data = new Dictionary<string, Dictionary<string, Dictionary<string, StatData>>>();

	private static List<StatData> modifiedStatDataList;

	private static StatData modifiedStatData;

	public static void LoadPlayerSkills(string categoryModifier = "")
	{
		LoadData(playerSkillAssetPath, statFieldStr, playerBaseCategory, categoryModifier);
	}

	public static void LoadEnemySkills(string categoryModifier = "")
	{
		LoadData(enemySkillAssetPath, statFieldStr, enemyBaseCategory, categoryModifier);
	}

	public static void LoadData(string assetPath, string statID, string category, string categoryModifier = "")
	{
		string text = category + categoryModifier;
		if (!data.ContainsKey(statID))
		{
			data[statID] = new Dictionary<string, Dictionary<string, StatData>>();
		}
		data[statID][text] = new Dictionary<string, StatData>();
		Dictionary<string, StatData> dictionary = data[statID][text];
		SkillStatContainer skillStatContainer = JsonUtility.FromJson<SkillStatContainer>(ChaosBundle.Get<TextAsset>(assetPath).text);
		int num = skillStatContainer.skillStats.Length;
		bool flag = category == "Enemy";
		for (int i = 0; i < num; i++)
		{
			skillStatContainer.skillStats[i].Initialize();
			StatData statData = new StatData(skillStatContainer.skillStats[i], text);
			List<string> value = statData.GetValue<List<string>>("targetNames");
			if (value.Contains(Globals.allyHBStr) || value.Contains(Globals.enemyHBStr))
			{
				value.Add(Globals.ffaHBStr);
			}
			if (value.Contains(Globals.allyFCStr) || value.Contains(Globals.enemyFCStr))
			{
				value.Add(Globals.ffaFCStr);
			}
			if (flag)
			{
				switch (categoryModifier)
				{
				case "Only":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Remove(Globals.allyHBStr);
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Remove(Globals.allyFCStr);
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "FFA":
					if (value.Contains(Globals.allyHBStr))
					{
						value.Add(Globals.enemyHBStr);
					}
					if (value.Contains(Globals.allyFCStr))
					{
						value.Add(Globals.enemyFCStr);
					}
					break;
				case "AsAlly":
					value.Remove(Globals.ffaHBStr);
					value.Remove(Globals.ffaFCStr);
					break;
				}
				statData.currentLevel = 1;
			}
			dictionary[statData.GetValue<string>("ID")] = statData;
			globalSkillData[statData.GetValue<string>("ID")] = statData;
		}
	}

	public static StatData GetSkillData(string category, string skillID)
	{
		return GetStatData("Skills", category, skillID);
	}

	public static StatData GetStatData(string statID, string category, string skillID)
	{
		if (!data.ContainsKey(statID) || !data[statID].ContainsKey(category))
		{
			return null;
		}
		if (!data[statID][category].ContainsKey(skillID))
		{
			return (!globalSkillData.ContainsKey(skillID)) ? null : globalSkillData[skillID];
		}
		return data[statID][category][skillID];
	}

	public static List<StatData> GetAllStatData(string statID, string fullCategoryStr)
	{
		return data[statID][fullCategoryStr].Values.ToList();
	}

	public static void ModifyAllStatData(NumVarStatMod givenMod, string givenCategory, string statFieldStr, ModApplyConditional GivenConditional = null, bool addMod = true)
	{
		modifiedStatDataList = GetAllStatData("Skills", givenCategory);
		if (addMod)
		{
			for (int num = modifiedStatDataList.Count - 1; num > -1; num--)
			{
				modifiedStatData = modifiedStatDataList[num];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					modifiedStatData.AddMod(statFieldStr, givenMod);
				}
			}
		}
		else
		{
			for (int num2 = modifiedStatDataList.Count - 1; num2 > -1; num2--)
			{
				modifiedStatData = modifiedStatDataList[num2];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					modifiedStatData.RemoveMod(statFieldStr, givenMod.ID);
				}
			}
		}
		modifiedStatDataList.Clear();
		modifiedStatData = null;
	}

	public static void ModifyAllStatData(Dictionary<string, NumVarStatMod> givenDict, string givenCategory, ModApplyConditional GivenConditional = null, bool addMod = true)
	{
		if (givenDict == null)
		{
			return;
		}
		modifiedStatDataList = GetAllStatData("Skills", givenCategory);
		if (addMod)
		{
			for (int num = modifiedStatDataList.Count - 1; num > -1; num--)
			{
				modifiedStatData = modifiedStatDataList[num];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					foreach (KeyValuePair<string, NumVarStatMod> item in givenDict)
					{
						modifiedStatData.AddMod(item.Key, item.Value);
					}
				}
			}
		}
		else
		{
			for (int num2 = modifiedStatDataList.Count - 1; num2 > -1; num2--)
			{
				modifiedStatData = modifiedStatDataList[num2];
				if (GivenConditional == null || GivenConditional(modifiedStatData))
				{
					foreach (KeyValuePair<string, NumVarStatMod> item2 in givenDict)
					{
						modifiedStatData.RemoveMod(item2.Key, item2.Value.ID);
					}
				}
			}
		}
		modifiedStatDataList.Clear();
		modifiedStatData = null;
	}
}
using System;
using System.Collections.Generic;
using Chaos.DictionaryExtensions;
using UnityEngine;

public class StatData
{
	public static string idStr = "ID";

	public static string eleStr = "elementType";

	public static string subEleStr = "subElementType";

	public static string showNumStr = "showDamageNumber";

	public static string showEffStr = "showDamageEffect";

	public static string shakeCamStr = "shakeCamera";

	public static string targetStr = "targetNames";

	public static string sameTrgStr = "sameTargetImmunityTime";

	public static string sameAtkStr = "sameAttackImmunityTime";

	public static string canStunStr = "canHitStun";

	public static string stunDurStr = "hitStunDurationModifier";

	public static string kbMultiStr = "knockbackMultiplier";

	public static string kbOverStr = "knockbackOverwrite";

	public static string damageStr = "damage";

	public static string cdStr = "cooldown";

	public static string durStr = "duration";

	public static string hitCountStr = "hitCount";

	public static string intervalStr = "damageInterval";

	public static string spawnStr = "spawnCount";

	public static string healthStr = "baseHealth";

	public static string critChStr = "criticalHitChance";

	public static string critDmgStr = "criticalDamageModifier";

	public static string isStatStr = "isStatusEffect";

	public static string rootChStr = "rootChance";

	public static string rootDurStr = "rootDuration";

	public static string chaosChStr = "chaosChance";

	public static string chaosLvStr = "chaosLevel";

	public static string burnChStr = "burnChance";

	public static string burnLvStr = "burnLevel";

	public static string slowChStr = "slowChance";

	public static string slowLvStr = "slowLevel";

	public static string psnChStr = "poisonChance";

	public static string psnLvStr = "poisonLevel";

	public static string shockChStr = "shockChance";

	public static string shockLvStr = "shockLevel";

	public static string frzChStr = "freezeChance";

	public static string frzDurStr = "freezeDuration";

	public static string odDmgStr = "overdriveDamageMultiplier";

	public static string odProgStr = "overdriveProgressMultiplier";

	public static string odSingleStr = "overdriveSingleIncrease";

	public Dictionary<string, object> statDict = new Dictionary<string, object>();

	public string category;

	public int currentLevel;

	public Dictionary<string, SyncedNumVarStat> numVarStatDict;

	public Dictionary<string, BoolVarStat> boolVarStatDict;

	public StatData(SkillStats givenSS, string givenCategory)
	{
		numVarStatDict = new Dictionary<string, SyncedNumVarStat>();
		boolVarStatDict = new Dictionary<string, BoolVarStat>();
		category = givenCategory;
		currentLevel = 0;
		LoadStatDict(givenSS);
	}

	public bool HasOverrideMod(string fieldName)
	{
		if (numVarStatDict.ContainsKey(fieldName))
		{
			return numVarStatDict[fieldName].HasOverrideMod;
		}
		if (boolVarStatDict.ContainsKey(fieldName))
		{
			return boolVarStatDict[fieldName].HasOverrideMod;
		}
		return false;
	}

	public void EnsureVarStatEntry(string fieldName)
	{
		if (!numVarStatDict.ContainsKey(fieldName))
		{
			numVarStatDict[fieldName] = new SyncedNumVarStat(0f);
		}
		if (!boolVarStatDict.ContainsKey(fieldName))
		{
			boolVarStatDict[fieldName] = new BoolVarStat(newBaseVal: false);
		}
	}

	public void AddMod(string fieldName, NumVarStatMod newMod)
	{
		if (!numVarStatDict.ContainsKey(fieldName))
		{
			numVarStatDict[fieldName] = new SyncedNumVarStat(0f);
		}
		numVarStatDict[fieldName].AddMod(newMod);
	}

