	public Dictionary<string, DoTEffect> dotDict;
	private List<string> dotIDList;
	public int ActiveDotCount => dotDict.Values.Count;
	public DoTManager(Entity newEntity)
	{
		dotDict = new Dictionary<string, DoTEffect>();
		dotIDList = new List<string>();
		entity = newEntity;
	}
	public void Update()
	{
		if (dotDict.Count == 0)
		{
			return;
		}
		dotIDList.AddRange(dotDict.Keys);
		for (int num = dotIDList.Count - 1; num >= 0; num--)
		{
			if (!DotIsActive(dotIDList[num]))
			{
				AnnounceStatusEvent(dotDict[dotIDList[num]], givenStatus: false);
				dotDict.Remove(dotIDList[num]);
			}
		}
		dotIDList.Clear();
	}
	public bool HasDot(string dotID)
	{
		return dotDict.ContainsKey(dotID) && dotDict[dotID] != null;
	}
	public bool DotIsActive(string givenID)
	{
		return HasDot(givenID) && !dotDict[givenID].Update();
	}
	public void AddDot(DoTEffect newDot)
	{
		if (HasDot(newDot.ID))
		{
			if (dotDict[newDot.ID].skillLevel <= newDot.skillLevel)
			{
				dotDict[newDot.ID].skillLevel = newDot.skillLevel;
				dotDict[newDot.ID].InitDotVars();
				dotDict[newDot.ID].Refresh(newDot.hitCount, newDot.damageInterval);
				AnnounceStatusEvent(newDot, givenStatus: true);
			}
		}
		else
		{
			dotDict[newDot.ID] = newDot;
			newDot.Init();
			AnnounceStatusEvent(newDot, givenStatus: true);
		}
	}
	public void RemoveDot(string givenID)
	{
		if (HasDot(givenID))
		{
			dotDict[givenID].Stop();
		}
	}
	public void ApplyStopElement(ElementType givenElement)
	{
		switch (givenElement)
		{
		case ElementType.Fire:
			RemoveDot(SlowDotEffect.slowStatusStr);
			break;
		case ElementType.Air:
			RemoveDot(PoisonDotEffect.poisonStatusStr);
			break;
		case ElementType.Earth:
			RemoveDot(ShockDotEffect.shockStatusStr);
			break;
		case ElementType.Lightning:
			if (entity != null && entity.fsm != null && entity.fsm.currentStateName == "Frozen")
			{
				entity.fsm.QueueChangeState(entity.fsm.defaultStateName);
			}
			break;
		case ElementType.Water:
			RemoveDot(BurnDoTEffect.burnStatusStr);
			break;
		case ElementType.Chaos:
			RemoveDot(BurnDoTEffect.burnStatusStr);
			RemoveDot(SlowDotEffect.slowStatusStr);
			RemoveDot(PoisonDotEffect.poisonStatusStr);
			RemoveDot(ShockDotEffect.shockStatusStr);
			if (entity != null && entity.fsm != null && entity.fsm.currentStateName == "Frozen")
			{
				entity.fsm.QueueChangeState(entity.fsm.defaultStateName);
			}
			break;
		case ElementType.Neutral:
			break;
		}
	}
	public void RemoveAll(bool keepBuffs = true)
	{
		List<DoTEffect> list = new List<DoTEffect>();
		foreach (DoTEffect value in dotDict.Values)
		{
			if (value != null && (!keepBuffs || !value.isBuff))
			{
				list.Add(value);
			}
		}
		for (int i = 0; i < list.Count; i++)
		{
			list[i].CleanUp();
			RemoveDot(list[i].ID);
		}
	}
	public void AnnounceStatusEvent(DoTEffect givenDot, bool givenStatus)
	{
		if (entity != null && givenDot != null && !givenDot.isBuff)
		{
			entity.AnnounceStatusEffectEvent(givenDot.dotElement, givenStatus);
		}
	}
}

