	public class MinionDeadState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = "Dead";

		public bool destroyOnEnter;

		public string deadAudioID = string.Empty;

		public override void OnEnter()
		{
			parent.anim.Play(animName);
			if (parent.groupList != null)
			{
				parent.groupList.Remove(parent.gameObject);
			}
			if (parent.parentSummonList != null)
			{
				parent.parentSummonList.Remove(parent.gameObject);
			}
			if (parent.useSummonDuration && parent.durationBar != null)
			{
				parent.durationBar.EndCast();
				Object.Destroy(parent.durationBar.gameObject);
			}
			if (parent.healthBar != null)
			{
				parent.healthBar.SetBarVisible(givenStatus: false);
				Object.Destroy(parent.healthBar.gameObject);
			}
			if (parent.destroyOnDeath && destroyOnEnter)
			{
				CallDestroy();
			}
		}

		public override void Update()
		{
			if (!destroyOnEnter && parent.destroyOnDeath && parent.anim.AnimPlayed())
			{
				CallDestroy();
			}
		}

		private void CallDestroy()
		{
			if (deadAudioID != string.Empty)
			{
				SoundManager.PlayWithDistAndSPR(deadAudioID, parent.transform.position);
			}
			if (parent != null && parent.gameObject != null)
			{
				Object.Destroy(parent.gameObject);
			}
		}
	}

