using System;
public class SummonArmorItem : Item
{
	public static string staticID = "SummonArmorItem";
	private Player.SkillState currentSS;
	private NumVarStatMod armorMod;
	private float armorPerSkill = 0.04f;
	private int summonSkillCount;
	protected override string ExtraInfo => PercentToStr(armorMod, "+");
	public SummonArmorItem()
	{
		ID = staticID;
		category = Category.Misc;
		armorMod = new NumVarStatMod(ID, 0f);
	}
	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}
	private void SetEventHandlers(bool givenStatus)
	{
		if (SetParentAsPlayer())
		{
			SetModStatus(givenStatus);
			Player player = parentPlayer;
			player.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillPickUp));
			Player player2 = parentPlayer;
			player2.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Remove(player2.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
			if (givenStatus)
			{
				Player player3 = parentPlayer;
				player3.skillPickUpEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player3.skillPickUpEventHandlers, new Player.SkillEventHandler(OnSkillPickUp));
				Player player4 = parentPlayer;
				player4.assignSkillSlotEventHandlers = (Player.AssignSkillSlotEventHandler)Delegate.Combine(player4.assignSkillSlotEventHandlers, new Player.AssignSkillSlotEventHandler(OnSkillAssign));
			}
		}
	}
	private void OnSkillPickUp(Player.SkillState newSkill)
	{
		SetModStatus(givenStatus: true);
	}
	private void OnSkillAssign(Player.SkillState newSkill, int skillSlotNum)
	{
		SetModStatus(givenStatus: true);
	}
	private void SetModStatus(bool givenStatus)
	{
		if (parentPlayer == null)
		{
			return;
		}
		if (givenStatus)
		{
			summonSkillCount = 0;
			for (int num = parentPlayer.assignedSkills.Length - 1; num >= 0; num--)
			{
				if (Item.IsSummonSkill(parentPlayer.assignedSkills[num]))
				{
					summonSkillCount++;
				}
			}
			if (Item.IsSummonSkill(parentPlayer.stockSkill))
			{
				summonSkillCount++;
			}
			armorMod.modValue = (float)summonSkillCount * armorPerSkill;
		}
		parentPlayer.health.armorStat.Modify(armorMod, givenStatus);
	}
