	protected virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new CloneIdleState("Idle", fsm, this));
		fsm.AddState(new CloneDashState("Dash", fsm, this));
		fsm.AddState(new CloneSlideState("Slide", fsm, this));
		fsm.AddState(new CloneDeadState("Dead", fsm, this));
		fsm.ChangeState("Slide");
	}
