	{
		if (fsm != null)
		{
			fsm.currentState.FixedUpdate();
		}
	}
	protected virtual void SetEventHandlers(bool givenStatus)
	{
		if (!(parentPlayer == null))
		{
			Player player = parentPlayer;
			player.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new Player.SkillEventHandler(OnParentDash));
			if (givenStatus)
			{
				Player player2 = parentPlayer;
				player2.skillExecEventHandlers = (Player.SkillEventHandler)Delegate.Combine(player2.skillExecEventHandlers, new Player.SkillEventHandler(OnParentDash));
			}
		}
	}
