			facingDir = Globals.GetPrimaryDirection(moveVector);
		}
		anim.PlayDirectional(givenName + facingDir, -1, givenAnimTime);
		transform.localScale = ((facingDir != FacingDirection.Left) ? Vector3.one : Globals.ScaleVecFlipX);
	}
	protected void CalculateMoveVector()
	{
		if (!(parentPlayer == null))
		{
			if (dashToParent)
			{
				moveVector = (parentPlayer.transform.position - transform.position).normalized;
			}
			else
			{
				moveVector = (parentPlayer.transform.position + (Vector3)parentPlayer.movement.dashVector * 2.5f - transform.position).normalized;
			}
			movement.moveVector = moveVector;
		}
	}
	protected void SetDashAttackStatus(bool givenStatus)
	{
		if (givenStatus)
		{
			if (dashAttack == null)
			{
				dashAttack = Globals.ChaosInst<ChaosDashAttack>(ChaosDashAttack.Prefab, null, atkTrans.position, Globals.GetRotationQuaternion(moveVector));
				dashAttack.followTrans = atkTrans;
				dashAttack.attack.SetAttackInfo(skillCat, skillID, 2);
			}
			dashAttack.attack.knockbackOverwriteVector = moveVector;
			dashAttack.transform.localEulerAngles = Globals.GetRotationVector(moveVector);
			SoundManager.PlayWithDistAndSPR("ChaosDash", atkTrans.position);
		}
		if (dashAttack != null)
		{
			dashAttack.gameObject.SetActive(givenStatus);
		}
	}
