	private void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new SpawnState("Spawn", fsm, this));
		fsm.AddState(new TurretDeadState("Dead", fsm, this));
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.ChangeState("Spawn");
	}
	public override void InitComponents()
	{
