		eyeLight = transform.Find("TurretEye/Point light").GetComponent<Light>();
	}
	private void InitAlignment()
	{
		if (isEnemy)
		{
			hurtBox.name = "EnemyHurtBox";
			floorContact.name = "EnemyFloorContact";
			hurtBox.tag = "Untagged";
			hurtBox.layer = LayerMask.NameToLayer("Enemy");
			gameObject.tag = "Untagged";
			gameObject.layer = LayerMask.NameToLayer("Enemy");
			Enemy.AddEnemy(gameObject);
			GameController.allies.Remove(gameObject);
			skillCategory = Enemy.globalEnemySkillCategory;
			skillID = "LaserBolt";
			curTurretProp = turretProperties[0];
		}
		else
		{
			hurtBox.name = "AllyHurtBox";
			floorContact.name = "AllyFloorContact";
			hurtBox.tag = "Ally";
			hurtBox.layer = LayerMask.NameToLayer("Default");
			gameObject.tag = "Ally";
			gameObject.layer = LayerMask.NameToLayer("Default");
			GameController.allies.Add(gameObject);
			GameController.enemies.Remove(gameObject);
			curTurretProp = turretProperties[1];
			durationBar = UnityEngine.Object.Instantiate(ChaosBundle.Get("Assets/Prefabs/UI/CastBar.prefab")).GetComponent<CastBar>();
			durationBar.parentTrans = transform;
			durationBar.SetBarDimensions(0.44f, 0.56f, 0.45f, 0.46f);
			durationBar.StartCast(ChaosStopwatch.Begin(curTurretProp.lifeTime), givenStatus: false);
		}
		barrageDelayStopwatchID = -1;
	}
	public void TrackClosestTarget(Transform targetTrans = null)
	{
		List<GameObject> list = null;
		List<GameObject> excludeList = null;
		List<GameObject> list2 = null;
		if (isEnemy)
		{
			list = GameController.allies;
		}
		else
		{
			list = GameController.enemies;
			if (parentPlayer != null)
			{
				excludeList = parentPlayer.playerSummonsList;
			}
		}
		list2 = Entity.GetAllTargetsInRange(list, transform.position, curTurretProp.attackRange, playerTagOnly: false, excludeList);
		closestTargetInfo = null;
		while (list2.Count > 0)
		{
			closestTargetInfo = Entity.GetClosestTarget(list2, transform.position, curTurretProp.attackRange, playerTagOnly: false, excludeList);
			if (closestTargetInfo != null && Entity.HasLineOfSight(transform.position, closestTargetInfo.position, curTurretProp.attackRange, lineOfSightLayerMask))
			{
				break;
			}
			list2.Remove(closestTargetInfo.gameObject);
			closestTargetInfo = null;
		}
	}
	private void LookAtTarget(Vector3 targetPos)
	{
		turretIris.localPosition = ((!(targetPos == Vector3.zero)) ? ((targetPos - turretIris.position).normalized / 9f) : targetPos);
	}
