using System;
public class OneHPOneDamage : Item
{
	public static string staticID = "OneHPOneDamage";
	private NumVarStatMod overrideMod;
	private NumVarStatMod finalBossMod;
	public OneHPOneDamage()
	{
		ID = staticID;
		category = Category.Offense;
		isCursed = true;
		hubOnly = true;
		overrideMod = new NumVarStatMod(ID, 1f, 0, VarStatModType.Override);
		finalBossMod = new NumVarStatMod(ID, 1f, 0, VarStatModType.Override, fillToNewMax: true);
	}
	public override void Activate()
	{
		SetModStatus(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetModStatus(givenStatus: false);
	}
	private void SetModStatus(bool givenStatus)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!(player == null))
			{
				player.health.damageTakenStat.Modify(overrideMod, givenStatus);
				player.health.healthStat.Modify(overrideMod, givenStatus);
				player.health.shieldStat.Modify(overrideMod, givenStatus);
			}
		}
		Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Remove(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
		if (givenStatus)
		{
			Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Combine(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
		}
		for (int j = 0; j < GameController.enemies.Count; j++)
		{
			if (GameController.enemies[j] != null)
			{
				ApplyEnemyMods(GameController.enemies[j].GetComponent<Enemy>(), givenStatus);
			}
		}
		SummonedEntity.useHealthOverride = givenStatus;
	}
	private void OnEnemySpawn(Enemy givenEnemy)
	{
		ApplyEnemyMods(givenEnemy, givenStatus: true);
	}
	private void ApplyEnemyMods(Enemy givenEnemy, bool givenStatus)
	{
		if (givenEnemy != null && givenEnemy.health != null)
		{
			givenEnemy.health.damageTakenStat.Modify(overrideMod, givenStatus);
			givenEnemy.health.healthStat.Modify(overrideMod, givenStatus);
			if (givenEnemy is FinalBoss)
			{
				((FinalBoss)givenEnemy).chaosShieldState.SetShieldMod((!givenStatus) ? null : finalBossMod);
			}
			else
			{
				givenEnemy.health.shieldStat.Modify(overrideMod, givenStatus);
			}
		}
	}
}
