public void RestoreHealth(int restoredHealth, bool showDisplayText = true, bool playSound = true, bool fullyRestoreHealth = false, bool useHealEnterEvent = true)
{
	healRestoreAmount = Mathf.CeilToInt((!fullyRestoreHealth) ? (healModifierStat.CurrentValue * (float)restoredHealth) : (healthStat.ModifiedValue - (float)CurrentHealthValue));
	isCriticalHeal = !fullyRestoreHealth && Random.value < critHealModStat.CurrentValue;
	if (isCriticalHeal)
	{
		healRestoreAmount *= 2;
	}
	if (useHealEnterEvent && healEnterEventHandlers != null)
	{
		healEnterEventHandlers(ref healRestoreAmount);
	}
	calcOverHeal = Mathf.Max(0, Mathf.CeilToInt((float)(CurrentHealthValue + healRestoreAmount) - healthStat.ModifiedValue));
	CurrentHealthValue += healRestoreAmount;
	if (healEventHandlers != null)
	{
		healEventHandlers(healRestoreAmount, calcOverHeal);
	}
	if (healRestoreAmount <= 0)
	{
		return;
	}
	if (showDisplayText)
	{
		string displayText = healRestoreAmount.ToString();
		Vector2 originVector = entityScript.hurtBoxTransform.position;
		Color fillColor = healColor;
		Color defaultBorderColor = OverheadNumber.defaultBorderColor;
		Vector3 position = entityScript.hurtBoxTransform.position;
		Transform hurtBoxTransform = entityScript.hurtBoxTransform;
		float scaleVal = ((!isCriticalHeal) ? 1f : 2f);
		bool showCritSplash = isCriticalHeal;
		CritType critType = (isCriticalHeal ? CritType.Heal : CritType.Default);
		OverheadNumberPool.DisplayOverheadNumber(displayText, originVector, fillColor, defaultBorderColor, position, hurtBoxTransform, scaleVal, showCritSplash, OverheadNumberIcon.None, critType);
	}
	if (playSound && !LoadingScreen.loading)
	{
		string displayText = "Heal";
		float scaleVal = ((!isCriticalHeal) ? 1f : 1.25f);
		SoundManager.PlayAudio(displayText, 1f, ignoreTimeRestriction: false, -1f, scaleVal);
		if (calcOverHeal < healRestoreAmount && HealthPercentage >= 1f)
		{
			SoundManager.PlayAudio("FullHealth");
		}
	}
}
